/* Bundle pricing: average base programme + average workshop; floor discounted total to 500 RUB. */
(()=>{'use strict';
const catalog=window.TEATR_CATALOG,all=Object.values(catalog).flatMap(c=>c.programs),find=id=>all.find(p=>p.id===id),workshops=catalog.workshop.programs;
const definitions={'combo-crystal':{show:'crystal-story'},'combo-snow':{show:'snow-whirl'},'combo-lab':{show:'winter-lab'},'combo-battle':{quiz:true},'combo-craft':{workshop:true},'combo-mega':{showChoice:true,workshop:true}};
const ids=Object.keys(definitions),periods=['До 19 декабря включительно','20–29 декабря','30 декабря','31 декабря · 09:00–18:00','31 декабря · 18:00–23:00','Новогодняя ночь · 23:00–03:00','1–7 января, после новогодней ночи','После 7 января'];
const allowed={base:['christmas-tree','ice-adventure'],show:['crystal-story','winter-lab','snow-whirl'],quiz:catalog.quiz.programs.map(p=>p.id),workshop:workshops.map(p=>p.id)};
function clean(v={}){v=v&&typeof v==='object'?v:{};const out={period:Number.isInteger(v.period)&&v.period>=0&&v.period<8?v.period:0,guests:[5,10,20,30,31].includes(Number(v.guests))?Number(v.guests):10};for(const [key,list]of Object.entries(allowed))out[key]=list.includes(v[key])?v[key]:list[0];return out}
function parts(id,v){const d=definitions[id];if(!d)return[];const o=clean(v);return [o.base,d.show|| (d.showChoice?o.show:null),d.quiz?o.quiz:null,d.workshop?o.workshop:null].filter(Boolean).map(find)}
function quote(id,v){const d=definitions[id];if(!d)return null;const o=clean(v),items=parts(id,o),base=(find('christmas-tree').prices[o.period]+find('ice-adventure').prices[o.period])/2;let average=base,actual=find(o.base).prices[o.period];for(const p of items.slice(1)){if(p.category==='workshop'){if(o.guests>30)return{price:null,minutes:items.reduce((n,p)=>n+p.minutes,0),items,options:o};const rate=p.groupPrices.find(r=>r.max>=o.guests);actual+=rate.price;average+=workshops.reduce((n,p)=>n+p.groupPrices.find(r=>r.max>=o.guests).price,0)/workshops.length}else{actual+=p.prices[o.period];average+=p.prices[o.period]}}const price=Math.floor(average*(id==='combo-mega'?.75:.8)/500)*500;return{price,actual,saving:actual-price,minutes:items.reduce((n,p)=>n+p.minutes,0),items,options:o}}
function periodFor(date,time='12:00'){if(!/^\d{4}-\d{2}-\d{2}$/.test(date||''))return 0;const [,m,d]=date.split('-').map(Number),t=/^\d{2}:\d{2}$/.test(time)?time:'12:00';if(m===1){if(d===1&&t<'03:00')return 5;return d<=7?6:7}if(m!==12||d<=19)return 0;if(d<=29)return 1;if(d===30)return 2;if(t>='23:00')return 5;if(t>='18:00')return 4;return 3}
const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
function describe(id,v){const q=quote(id,v);if(!q)return'';return q.items.map(p=>p.title).join(' + ')+` · ${q.minutes} минут · ${periods[q.options.period]}`+(definitions[id].workshop?` · МК: ${q.options.guests>30?'более 30':'до '+q.options.guests} участников`:'')+' · '+(q.price===null?'Индивидуальный расчёт':money(q.price))+' · дорога отдельно'}
window.ComboPricing={ids,definitions,allowed,periods,clean,quote,parts,money,describe,periodFor};
})();
